function 炉石()
	local lsmap = 炉石位置()
	local lsd=0
	while 小地图名() ~= lsmap and 地图名() ~= lsmap do 
		if 地图名() == "沙塔斯城" and 小地图名() == "旅店" and lsmap == "占星者之台" then
			lsd=1
			break
		end
		下马()
		使用物品("炉石")
		延时(3000)
		while 读条中() do 
			延时(1000)
		end
		if 地图名() == "死亡矿井" or 地图名() == "奥达曼" then
			while 战斗中() do
				技能输出()
			end
		end
		延时(3000)
		while 过图中() do 
			延时(500)
		end
		延时(1000)
		if 小地图名() ~= lsmap then
			跳()
			延时(2000)
		end
		if HP() <= 1 then
			释放灵魂()
			虚弱复活()
		end
		if 地图名() == lsmap or 小地图名() == "旅店" and lsmap == "占星者之台" then
			lsd=1
			break
		end
	end
	沙城回主城()
	if 在坐标范围(1631.6, 222.833, -43.1025,10) then
		幽暗城补充材料()
	end
	if 在坐标范围(-1297.67, 39.333, 129.209,20) then
		雷霆崖补充材料(1)
		if zy == "潜行者" then
			num = 背包物品数量("闪光粉")
			if num < 20 then
				路径走到("雷霆崖到飞机点",-1197.18, 27.5771, 176.948)
				打开NPC("塔尔")
				延时(500)
				打开NPC("塔尔")
				延时(1000)
				if 坐飞机到("奥格瑞玛") then
					while 在飞机上() do 
						延时(1000)
					end
				end
				if 地图名() == "奥格瑞玛" then
					路径走到("奥格飞行点下到法师传送",1656.82, -4357.65, 25.3364)
					奥格补充材料()
					路径走到("奥格飞行点下到法师传送",1674.78, -4322.38, 61.2465)
					if 在坐标范围(1674.78, -4322.38, 61.2465,10) then
						走到(1676.46, -4315.67, 61.5217,1)
						if 打开NPC("多拉斯") then
							延时(500)
						else
							打开NPC("多拉斯")
							延时(500)
						end
						if 坐飞机到("雷霆崖") then
						end
					end
				end
			end
			while 在飞机上() do 
				延时(1000)
			end
			if 地图名() == "雷霆崖" then
				路径走到("雷霆崖到飞机点",-1252.88, 65.2824, 127.355)
			end
		end
	end
	if 地图名() == "暴风城" then
		if lsd==1 then
			自动寻路(-8806.69, 628.75, 94.2283)
			走到(-8800.4, 623.82, 96.7738,1)
			走到(-8789.01, 611.279, 97.7687,1)
			打开NPC("玛尔达·维勒")
			延时(1500)
			对话选项(1)
			延时(1500)
			出售垃圾()
			走到(-8800.4, 623.82, 96.7738,1)
		end
	end
	铁炉堡补充材料()
	提升草药技能()
end
function 铁炉堡补充材料()
	if 地图名() == "铁炉堡" then
		if zy == "法师" then
			local num = 背包物品数量("传送符文")
			if 存在技能("召唤餐桌") then
				num2 = 背包物品数量("魔粉")
			else
				num2 = 100
			end
			if num < 4 or num2 < 20 then
				自动寻路(-4866.4, -867.937, 502.192)
				打开NPC("巴瑞姆·贾根斯塔德")
				延时(1000)
				if num < 4 then
					购买物品(7,20-num)
				end
				if num2 < 20 then
					购买物品(9,20-num2)
				end
				延时(2000)
				自动寻路(-4864.96, -883.073, 501.66)
			end
		elseif zy == "圣骑士" then
			num = 背包物品数量("王者印记")
			if num < 20 then
				自动寻路(-4866.4, -867.937, 502.192)
				打开NPC("巴瑞姆·贾根斯塔德")
				延时(1000)
				购买物品(19,100-num)
				延时(2000)
				自动寻路(-4864.96, -883.073, 501.66)
			end
		end
		if 背包空格() < 20 then
			自动寻路(-4876.7, -967.509, 505.074)
			打开NPC("曼高恩·火锤")
			延时(1000)
			出售垃圾()
			出售垃圾()
			自动寻路(-4879.56, -946.395, 501.459)
		end
		if zy == "潜行者" then
			盗贼补充()
		end
	end
end
function 炉石回城()
	local lmap=炉石位置()
	if lmap ~= "尼耶尔前哨站" and lmap ~= "葬影村" and lmap~="石爪峰" and lmap ~= "烈日石居" then
		提示("炉石在"..lmap.."，准备去正确地点绑定")
		--[[while lmap ~= "尼耶尔前哨站" and lmap ~= "葬影村" and lmap~="石爪峰" do 
			延时(10000)
			lmap=炉石位置()
			按键("space")
		end--]]
		玛拉顿出本()
		while lscheck==1 and lmap ~= "尼耶尔前哨站" and lmap ~= "葬影村" and lmap~="石爪峰" and lmap ~= "烈日石居" do 
			if zz == "亡灵" or zz=="巨魔" then
				if 地图名() == "雷霆崖" then
					if 在坐标范围(-1261.44, 24.9744, 128.187,15) then
						路径走到("雷霆崖旅店到银行",-1261.51, 45.6542, 127.442)
					end
					if 在路径范围("雷霆崖传送点到电梯") then
						路径走到("雷霆崖传送点到电梯",-1209.47, 130.584, 134.497)
						路径走到("雷霆崖到飞机点",-1251.01, 66.7901, 127.379)
						走到(-1261.51, 45.6542, 127.442,1)
					end
					路径走到("雷霆崖到飞机点",-1197.18, 27.5771, 176.948)
					打开NPC("塔尔")
					延时(500)
					打开NPC("塔尔")
					延时(1000)
					if 坐飞机到("烈日石居") then
					elseif 坐飞机到("葬影村") then
					end
				end
				if HP() > 1 then
					if 在坐标范围(-1440.1, 1974.97, 85.8554,100) then
						自动寻路(-1593.5, 3149.69, 46.4947,35)
					end
					执行脚本("玛拉顿到葬影村.lua")
				end
				if HP() <= 1 then
					释放灵魂()
					虚弱复活()
					使用技能("冰甲术")
					if 炉石位置() ~= "烈日石居" then
						上马()
						自动寻路(-1593.5, 3149.69, 46.4947,35)
						路径走到("玛拉顿到葬影村",-1593.5, 3149.69, 46.4947)
						打开NPC("旅店老板希科瓦")
						延时(1000)
						对话选项(1)
						延时(1000)
						运行宏("/click StaticPopup1Button1")
						延时(1000)
					end
				end
			else
				if HP() > 1 then
					if 在坐标范围(-1440.1, 1974.97, 85.8554,100) then
						自动寻路(-1593.5, 3149.69, 46.4947,35)
					end
					执行脚本("玛拉顿到尼耶尔前哨站.lua")
				end
				if HP() <= 1 then
					释放灵魂()
					虚弱复活()
					使用技能("冰甲术")
					if 炉石位置() ~= "石爪峰" then
						上马()
						自动寻路(137.748, 1325.52, 193.499)
					end
				end
			end
			lmap=炉石位置()
		end
		提示("炉石已绑定："..炉石位置())
	end
	while lscheck==1 and 小地图名() ~= lmap and HP()>1 do
		if 地图名() == "玛拉顿" then
			while 战斗中() do
				x,y,z = 当前坐标()
				if 坐标范围怪物数量(x,y,z,10) == 0 then
					x,y,z = 目标坐标()
					朝向坐标(x,y,z)
					使用技能("寒冰箭")
					延时(300)
					while 读条中() do 
						延时(100)
					end
				else
					使用技能("魔爆术")
					延时(1400)
				end
			end
		end
		使用技能("寒冰护体")
		延时(1500)
		提示("炉石回城")
		使用物品("炉石")
		延时(10000)
		for i=1,10,1 do 
			if 过图中() or 地图名() == "凄凉之地" or 地图名()=="石爪山脉" then
				break
			end
			延时(1000)
		end
		while 过图中() do 
			延时(1000)
		end
		if 地图名() ~= "凄凉之地" and 地图名() ~= "石爪山脉" then
			提示("炉石可能未冷却或绑错了地方")
			按键("space")
			玛拉顿出本()
			if zhenying == "联盟" then
				执行脚本("玛拉顿到尼耶尔前哨站.lua")
			else
				执行脚本("玛拉顿到葬影村.lua")
			end
		end
		延时(3000)
		if HP() == 0 then
			释放灵魂()
		end
	end
end
function 玛拉顿进本()
	if 在坐标范围(-1182.86, 2872.28, 85.7709,60) then
		if 是否队长() then
			运行宏("/p 进本")
			自由拾取()
		end
		--MLD门口处理()
		--走到(-1182.86, 2872.28, 85.7709,1)
		取消BUFF("寒冰屏障")
		朝向坐标(-1181.17, 2855.86, 85.2396)
		按键("w")
		延时(300)
		--使用技能("闪现术")
		移动("前",5000)
		while 过图中() do 
			延时(1000)
		end
		waitTime=0
