function 主城存取仓(cunqu)
	if cunqu == nil then
		cunqu = 0
	end
	if zy == "法师" and 背包物品数量("传送符文") == 0 then
		mldcc=0
		return
	end
	if zy == "法师" and 背包物品数量("传送符文") > 0 then
		销毁物品("法力蓝宝石",1)
		销毁物品("法力红宝石",1)
		销毁物品("法力黄水晶",1)
		if zhenying == "部落" then
			if mldcc == 1 then
				if 法师传送到("幽暗城") then
				elseif 法师传送到("奥格瑞玛") then
				end
				if 地图名() == "奥格瑞玛" then
					奥格到提瑞斯法林地()
				end
				if 地图名() == "提瑞斯法林地" or 小地图名() == "洛丹伦废墟" then
					提瑞斯法林地到幽暗城()
				end
				if 地图名() == "幽暗城" then
					幽暗城补充材料()
					路径走到("幽暗城法师传送到旅店电梯",1601.29, 240.396, -51.1799)
					下马()
					延时(1000)
					if 打开NPC("伦道夫·蒙泰古") then
						延时(1000)
						if cunqu == nil or cunqu==0 then
							存仓()
						else
							取仓()
						end
						延时(1000)
					end
				end
			else
				if 法师传送到("雷霆崖") then
				elseif 法师传送到("奥格瑞玛") then
				elseif 法师传送到("幽暗城") then
				end
				提瑞斯法林地到奥格()
				if 地图名() == "奥格瑞玛" or 地图名() == "雷霆崖" then
					奥格到雷霆崖()
					雷霆崖补充材料(1)
				end
				if 地图名() == "雷霆崖" then
					if not 在坐标范围(-1261.23, 22.8048, 128.187,5) then
						if 在路径范围("雷霆崖传送点到电梯") then
							路径走到("雷霆崖传送点到电梯",-1209.47, 130.584, 134.497)
							路径走到("雷霆崖到飞机点",-1251.01, 66.7901, 127.379)
							走到(-1261.51, 45.6542, 127.442,1)
						else
							路径走到("雷霆崖旅店到草药训练师",-1261.51, 45.6542, 127.442)
						end
						路径走到("雷霆崖旅店到银行",-1261.23, 22.8048, 128.187)
					end
					if 打开NPC("阿特帕") then
						延时(1000)
						if cunqu == nil or cunqu==0 then
							存仓()
						else
							取仓()
						end
						延时(1000)
					end
				end
			end
			
		else
			if 法师传送到("铁炉堡") then
			elseif 法师传送到("暴风城") then
			end
			暴风城巫师圣殿出门()
			if 地图名() == "暴风城" or 地图名() == "矿道地铁" then
				暴风城到铁炉堡()
			end
			if 地图名() == "铁炉堡" then
				法师补充()
				自动寻路(-4876.7, -967.509, 505.074)
				if 打开NPC("曼高恩·火锤") then
					延时(1000)
					出售垃圾()
					出售垃圾()
				end
				自动寻路(-4879.56, -946.395, 501.459)
				自动寻路(-4888.45, -995.103, 504.758)
				走到(-4888.49, -994.984, 504.723,1)
				if 打开NPC("拜雷·石衣") then
					延时(1000)
					if cunqu == nil or cunqu==0 then
						存仓()
					else
						取仓()
					end
					延时(1000)
				end
			end
		end
	end
end
