function 玛拉顿出本(chu)
	if mldbuchu ~= nil and mldbuchu == 1 then
		return
	end
	if 在副本() and 地图名() == "玛拉顿" then
		路径寻路("玛拉顿出副本")
		寻路结束()
		朝向坐标(761.285, -626.233, -32.7031)
		使用技能("寒冰护体")
		if chu == nil then
			if 是否队长() then
				运行宏("/p 出本")
				延时(1000)
			end
			自动跑()
			延时(3000)
			local wt=1
			while not 在坐标范围(-1182.86, 2878.28, 85.92,30) and HP()>0 do 
				延时(1000)
				wt=wt+1
				if wt>30 then
					if 在坐标范围(758.968, -608.089, -32.8245,80) then
						走到(758.968, -608.089, -32.8245,1)
						延时(5000)
						朝向坐标(761.285, -626.233, -32.7031)
						自动跑()
						wt=0
					end
				end
				while 过图中() do 
					延时(300)
				end
				val = 检查挂机方案()
				if val == 11 or val == 22 then
					return
				end
			end
			寻路结束()
			if 战斗中() then
				使用技能("寒冰屏障")
			end
		end
	end
end
function 回蓝()
	if MP() < 3500 then
		使用物品("强效法力药水")
	end
	if MP() < 1200 then
		使用物品("法力红宝石")
		--使用物品("法力黄水晶")
	end
end
function 回血()
	if HP() / MaxHP() < 0.7 then
		运行宏("/use 特效治疗药水/n/use 优质治疗药水")
	end
end
function 绷带回血()
	if HP() < 1000 then
		if 背包物品数量("厚符文布绷带") > 0 then
			if 存在DEBUFF() then
				使用技能("寒冰屏障")
				延时(100)
				取消BUFF("寒冰屏障")
			end
			使用物品("厚符文布绷带")
			延时(3000)
			return true
		end
	end
	return false
end
