function 树杈上打怪()
	if 精英剩余数量() == 0 or HP() <= 1 or 地图名() ~= "玛拉顿" then
		延时(500)
		return
	end
	local done=0
	while HP()>1 do
		if 精英剩余数量() == 0 or HP() <= 1 then
			return
		end
		回蓝()
		回血()
		if 低处下雪() then
			local st=os.clock()
			延时(500)
			if 读条中() then
				延时(500)
				for ii=1,60,1 do 
					延时(100)
					if not 读条中() then
						break
					end
					if MLD_坐标范围精英数量(784.771, -491.128, -40.0365, 8) < 3 and 需上() then
						done=1
						break
					end
					if os.clock()-st>=7 then
						break
					end
				end
			end
			if done == 1 then
				return
			end
			if 存在BUFF("寒冰护体") == false then
				使用技能("寒冰护体")
				if done == 1 or 需上() then
					return
				end
				延时(200)
				if 存在BUFF("寒冰护体") then
					for iii=1,10 do
						延时(100)
						if 需上() then
							done=1
							break
						end
					end
				end
			end
			if done==1 then
				return
			end
		else
			return
		end
	end
end
function 台子上打怪()
	if 精英剩余数量() == 0 or HP() <= 1 or 地图名() ~= "玛拉顿" then
		return
	end
	local done=0
	local f=0
	while HP()>1 do
		if 精英剩余数量() == 0 or HP() <= 1 or 小鬼剩余数量() > 8 and HP()/MaxHP() < 0.8 and 精英剩余数量() > 10 then
			return
		end
		if 需下() or 需要跑圈() then
			done=1
			return
		end
		回蓝()
		回血()
		if 高处下雪() then
			local st=os.clock()
			f=f+1
			延时(200)
			for ii=1,60,1 do 
				if 需下() then
					done=1
					return
				end
				延时(100)
				if not 读条中() then
					break
				end
				if os.clock()-st>=7.3 then
					break
				end
			end
			if f>2 and 小鬼剩余数量() > 8 and HP()/MaxHP() < 0.8 and 精英剩余数量() > 10 then
				return
			end
		else
			return
		end
	end
end
function 销毁低价物品()
	销毁物品("法力药水",1)
	while 背包物品数量("浮渣覆盖的袋子")>0 and HP()>1 do 
		使用物品("浮渣覆盖的袋子")
		延时(1000)
		销毁物品("法力药水",1)
		if 背包空格()==0 then
			销毁物品("浮渣覆盖的袋子",1)
		end
	end
	销毁物品("治疗药水",1)
	销毁物品("初级治疗药水",1)
	销毁物品("次级法力药水",1)
	销毁物品("初级法力药水",1)
	销毁物品("亚麻布|地根|荆棘|银叶|莓汁|熏肉|宝箱|魔皇|黑蘑|性之心|活根|南草|胡须|神花|卷轴|配方|结构图|设计图|图样：|跌打|斯之泪|力红")
	if 背包空格() < maxfree and not 炉石可用() then
		销毁物品("法甜|苏打|晶水")
		if 背包空格() < maxfree and not 炉石可用() then
			销毁物品("面包|丝绸")
		end
	end
	--[[if 存在技能("分解") then
		while 背包物品数量("花苗头饰") > 0 and 背包空格()>0 do
			运行宏("/cast 分解/n/use 花苗头饰")
