			延时(5000)
		end
	end--]]
end
function 扫地阶段(lx,chu)
	if lx==nil then
		lx=1
	end
	if HP() > 1 then
		销毁物品("法力蓝宝石",1)
		销毁物品("法力红宝石",1)
		销毁物品("法力黄水晶",1)
		销毁物品("魔法肉桂面包",1)
		销毁物品("魔法晶水",1)
		MLD摸尸体(lx)
		if 在副本() then
			路径寻路("玛拉顿出副本")
			销毁低价物品()
		end
		if 队伍人数() > 1 then
			队伍拾取()
		end
		if 背包空格() < maxfree then
			--[[路径寻路("玛拉顿出副本")
			寻路结束()--]]
			回城售卖()
		else
			if 在副本() then
				if mldbuchu==nil or mldbuchu==0 then
					玛拉顿出本(chu)
				end
			end
		end
	else
		释放灵魂()
	end
end
