		if 队伍人数() > 1 then
			队伍拾取()
		end
		if 背包空格() < maxfree then
			--[[路径寻路("玛拉顿出副本")
			寻路结束()--]]
			回城售卖()
		else
			if 在副本() then
				玛拉顿出本()
			end
		end
	else
		释放灵魂()
	end
end
function 扫地阶段3(chu)
	if HP() > 1 then
		销毁物品("法力蓝宝石",1)
		销毁物品("法力红宝石",1)
		销毁物品("法力黄水晶",1)
		销毁物品("魔法肉桂面包",1)
		销毁物品("魔法晶水",1)
		MLD摸尸体3()
		if 在副本() then
			if mincaiyao >= 245 then
				if 坐标范围有采集物(716.341, -509.04, -36.413,6) then
					路径走到("玛拉顿出副本",721.4, -480.01, -41.0782)
					走到(717.421, -510.043, -36.3309,1)
