				end
			end
			--闪现走到(768.207, -471.603, -40.9729,1)
			销毁低价物品()
			路径寻路("玛拉顿出副本")
			销毁低价物品()
		end
		if 队伍人数() > 1 then
			队伍拾取()
		end
		if 背包空格() < maxfree then
			--[[路径寻路("玛拉顿出副本")
			寻路结束()--]]
			回城售卖()
		else
			if 在副本() then
				if mldbuchu==nil or mldbuchu==0 then
					路径寻路("玛拉顿出副本")
					玛拉顿出本(chu)
				end
			end
		end
	else
		释放灵魂()
	end
end
function MLD进本(cz)
	if cz~=nil then
		需要重置=0
	end
	local fb=0
	if HP() <= 1 then
		延时(1000)
		if 在副本() and HP() == 0 then
			fb=1
		end
		释放灵魂()
		if fb==0 then
			x,y,z = 尸体坐标()
			if x > -900 or x < -1520 then
				虚弱复活()
				延时(5000)
				if HP() > 1 then
					使用技能("冰甲术")
					上马()
					return
				end
			else
				if math.abs(x+1443.49) > 0.5 or math.abs(y-1973.37) > 0.5 then
					提示("副本外死亡")
					延时(1000)
					
					路径走到("玛拉顿完美复活",1194.16,2877.97,85.8749)
					--[[按键("w",1)
					延时(1500)
					复活()
					延时(300)
					使用技能("寒冰护体")
					延时(1500)
					if HP() > 1 then
						使用技能("冰甲术")
					end
					按键("w",2)--]]
				end
			end
		end
		路径寻路("玛拉顿完美复活")
		if HP() == 1 then
			if 背包空格() >= maxfree then
				if 需要重置==1 then
					队伍拾取()
					重置副本()
					需要重置=0
					if 已重置次数 ~= nil then
						已重置次数=已重置次数+1
						置重置次数(已重置次数)
					end
				end
			end
			延时(3000)
			复活()
			if HP()>=1 then
				朝向坐标(-1181.17, 2855.86, 85.2396)
				移动("前",5000)
				延时(1000)
				while 过图中() do 
					延时(1000)
				end
				延时(3000)
				寻路结束()
			elseif HP() == 0 then
				释放灵魂()
				return
			end
			while 过图中() do 
				延时(1000)
			end
			if not 在副本() and HP()==1 and not 可复活() then
				脱离卡死()
				延时(1000)
				虚弱复活()
				延时(1000)
				return
			end
			if not 在副本() and HP() >= 1 then
				走到(-1171.22, 2880.92, 85.3206,1)
				延时(1000)
				while not 在副本() and HP()>0 do 
					if 可复活() then
						复活()
					end
					朝向坐标(-1181.17, 2855.86, 85.2396)
					按键("w",1)
					使用技能("闪现术")
					延时(500)
					移动("前",5000)
					while 过图中() do 
						延时(1000)
					end
					延时(1000)
					if not 在副本() then
						走到(-1171.22, 2880.92, 85.3206,1)
						延时(15000)
					end
					if HP() == 0 then
						释放灵魂()
						路径寻路("玛拉顿")
						复活()
					end
				end
			end
		end
	end
	map = 地图名()
	if HP() > 1 and (map ~= "凄凉之地" and map ~= "玛拉顿" or not 在副本() or 背包空格()<maxfree) then
		回城售卖()
		if HP() > 0 then
			if 需要重置==1 then
				重置副本()
				需要重置=0
				if 已重置次数 ~= nil then
					已重置次数=已重置次数+1
					置重置次数(已重置次数)
				end
			end
		end
		玛拉顿进本()
	end
end
function 回复状态()
	if 等级() >= 50 then
		mmp=4000
	else
		mmp=2500
	end
	if MP()<mmp then
		回满()
	end
	if HP() == 0 then
		return
	end
	清除目标()
	跳()
	延时(200)
	while MP() > mmp do
		使用技能("奥术智慧")
		延时(1400)
		if 存在BUFF("奥术智慧") then
			break
		end
	end
	使用技能("冰甲术")
	延时(1400)
	回满()
	跳()
	延时(1000)
	if 背包物品数量("法力红宝石") < 1 then
		使用技能("制造魔法红宝石")
		延时(1500)
		while 读条中() do 
			延时(200)
		end
		延时(500)
	end
	if 背包物品数量("法力黄水晶") < 1 then
		使用技能("制造魔法黄水晶")
		延时(1500)
		while 读条中() do 
			延时(200)
		end
		延时(500)
	end
	if HP() == 0 then
		return
	end
	回满()
	跳()
	延时(1000)
end
function MLD一阶段()
	if 队伍人数() > 1 then
		自由拾取()
	end
	回复状态()
	if 种族() == "侏儒" and not 存在BUFF("精神错乱") and not 存在BUFF("呀啊啊啊啊") then
		使用物品("美味风蛇")
	end
end
