	while 精英剩余数量() > 0 and HP() > 1 do 
		上树()
		树杈上打怪()
		上台子()
		台子上打怪()
		if 小鬼剩余数量() > 8 and HP()/MaxHP() < 0.8 and 精英剩余数量() > 10 or 需要跑圈() then
