function MLD收尾(sq,chu)
	清除目标()
	if HP() > 0 then
		使用技能("寒冰护体")
		延时(1500)
		上台子()
		使用技能("暴风雪")
		指向坐标(767.504, -475.74, -40.7071)
		for i=1,8 do
			延时(1000)
			if not 战斗中() or 坐标范围怪物数量(767.504, -475.74, -40.7071,12) == 0 then
				break
			end
		end
	end
	for i=1,2 do
		local f=0
		while 战斗中() and HP() > 0 do
			上台子()
			f=f+1
			local fight=0
			x,y,z = 最前坐标(0)
			while x~=0 and y~=0 and z~=0 and HP()>0 do
				使用技能("暴风雪")
				指向坐标(x,y,z)
				for i=1,7 do
					延时(1000)
					if not 读条中() or not 战斗中() or 坐标范围怪物数量(x,y,z,12) == 0 then
						break
					end
				end
				if not 存在BUFF("寒冰护体") then
					使用技能("寒冰护体")
					延时(500)
					if 存在BUFF("寒冰护体") then
						延时(1000)
					end
				end
				if MP() < 1300 then
					break
				end
				x,y,z = 最前坐标(0)
				fight = fight +1
				if fight > 1 then
					break
				end
			end
			清除目标()
			按键("Tab")
			延时(300)
			x,y,z = 目标坐标()
			if x~=0 and y~=0 and z~=0 then
				朝向坐标(x,y,z)
				使用技能("寒冰箭")
				while 读条中() do 
					延时(100)
				end
			end
			if MP() < 900 then
				使用物品("法力红宝石")
				延时(200)
				if MP() < 900 then
					使用物品("法力黄水晶")
				end
			end
			if not 存在BUFF("寒冰护体") then
				使用技能("寒冰护体")
				延时(500)
				if 存在BUFF("寒冰护体") then
					延时(1000)
				end
			end
		end
		延时(500)
	end
	if HP() > 1 then
		销毁物品("法力蓝宝石",1)
		销毁物品("法力红宝石",1)
		销毁物品("法力黄水晶",1)
		if sq == nil or sq==0 then
			上树()
			扫地阶段(1,chu)
		elseif sq==1 then
			上台子()
			玛拉顿出本(chu)
		end
	else
		释放灵魂()
	end 
end
function 教堂进本()
	if HP() == 0 then
		return
	end
	while not 在副本() and not 在坐标范围(2912.74, -825.01, 160.328,6) do
		if HP() == 0 then
			释放灵魂()
			延时(1000)
		end
		if HP() == 1 then
			x,y,z = 尸体坐标()
			路径走到("血色复活路径",x,y,z)
		end
		map = 地图名()
		if map=="希尔斯布莱德丘陵" or map == "银松森林" or zhenying == "联盟" and map=="提瑞斯法林地" then
			while not 在坐标范围(2907.68, -816.294, 160.327,30) do
				if 在坐标范围(-851.47, -545.129, 11.0545,120) then
					路径走到("南海镇到血色",-851.47, -545.129, 11.0545)
					发送邮件()
					自动寻路(-816.025, -573.763, 15.4053)
					打开NPC("罗伯特·埃比斯彻尔")
					延时(1000)
					出售垃圾()
					延时(1000)
					自动寻路(-796.697, -540.717, 16.4009)
				end
				map=地图名()
				if map=="希尔斯布莱德丘陵" or map=="银松森林" or map == "提瑞斯法林地" then
					if 炉石位置() == "南海镇" then
						路径走到("南海镇到血色",2907.68, -816.294, 160.327)
					end
				else
					路径走到("血色修理路径",949.777, -1434.65, 62.7751)
					打开NPC("莱纳德·波特")
					延时(1000)
					出售垃圾()
					延时(1000)
				end
				if 炉石位置() ~= "南海镇" then
					路径走到("血色修理路径",2907.68, -816.294, 160.327)
				end
				if HP() == 0 then
					释放灵魂()
				end
				if HP()==1 then
					x,y,z = 尸体坐标()
					自动寻路(x,y,z)
					复活()
				end
			end
		end
		路径走到("部落血色修理",2907.68, -816.294, 160.327)
		if 战斗中() then
			使用技能("寒冰护体")
			延时(1000)
			x,y,z = 目标坐标()
			朝向坐标(x,y,z)
			移动("后",300)
			while 战斗中() do 
				x,y,z = 目标坐标()
				朝向坐标(x,y,z)
				移动("后",100)
				延时(100)
				使用技能("寒冰箭")
				延时(300)
				while 读条中() do 
					延时(100)
				end
				延时(300)
			end
		end
		走到(2910.77, -815.987, 160.333,1,0,0.2)
		朝向坐标(2910.81, -818.836, 160.293)
		按键("w",1)
		延时(300)
		按键("w",2)
		if 打开身边目标()  then
			延时(500)
			while 读条中() do 
				延时(100)
			end
		end
		延时(300)
		按键("e",1)
		延时(500)
		按键("e",2)
		走到(2912.74, -825.01, 160.328,1)
	end
	while 在坐标范围(2917.16, -822.924, 160.327,40) and HP()>=1 do
		if not 在坐标范围(2912.74, -825.01, 160.328,6) then
			路径走到("血色复活路径",2915.11, -823.71, 160.328,1)
		else
			走到(2912.74, -825.01, 160.328,1)
		end
		朝向坐标(2926.97, -819.177, 160.328)
		if 是否队长() and HP()>1 then
			运行宏("/p 进本")
			延时(2000)
		end
		移动("前",3000)
		while 过图中() do 
			延时(1000)
		end
		if HP() == 1 then
			return
		end
		if not 在坐标范围(850.698, 1324.3, 18.6716,30) then
			走到(2911.51, -827.026, 160.327,1)
			延时(60000)
			if 等级() < 45 then
				return
			end
		end
		val = 检查挂机方案()
		if val == 11 or val == 22 then
			return
		end
	end
end
