function 战斗处理()
	if 战斗中() then
		nx,ny,nz = 当前坐标()
		if zy == "潜行者" then
			使用技能("消失")
			寻路结束()
			延时(3000)
			if 战斗中() then
				while 战斗中() do 
					技能输出()
				end
			end
			if HP() > 1 and not 存在BUFF("潜行") then
				使用技能("潜行")
			end
			走到(nx,ny,nz,1)
		elseif zy == "法师" then
			使用技能("寒冰护体")
			延时(1500)
			while 战斗中() do 
				使用技能("寒冰护体")
				延时(1500)
				while 坐标范围怪物数量(nx,ny,nz,8,"自由的幽魂") > 0 do
					使用技能("魔爆术")
					延时(1300)
					if not 存在BUFF("寒冰护体") then
						使用技能("寒冰护体")
						延时(1400)
					end
				end
				while 有目标() and HP()>1 do
					x,y,z = 目标坐标()
					if x ~= 0 or y~=0 then
						朝向坐标(x,y,z)
					end
					使用技能("寒冰箭")
					延时(300)
					while 读条中() do 
						延时(300)
					end
					使用技能("火焰冲击")
					延时(1300)
					if not 存在BUFF("寒冰护体") then
						使用技能("寒冰护体")
						延时(1400)
					end
				end
			end
			延时(1500)
			if HP() > 1 and MP()<2000 then
				使用技能("唤醒")
				延时(8000)
				回满()
			end
		elseif zy == "德鲁伊" then
			while 战斗中() do 
				while 有目标() and HP()>1 do
					技能输出()
				end
			end
			使用技能("回春术")
			延时(1500)
			潜行()
		end
		走到(nx,ny,nz,1)
	end

end
