function XS1进本()
	if HP()==0 then
		return
	end
	if not 在副本() then
		if 在坐标范围(2888.61, -826.871, 160.331,35) then
			while true do
				x,y,z= 当前坐标()
				if y<-826.5 then
					if zy == "潜行者" then
						while 存在BUFF("潜行") and HP()>1 do 
							取消BUFF("潜行")
							延时(500)
						end
					elseif zy=="法师" then
						使用技能("冰甲术")
						延时(1500)
						使用技能("寒冰护体")
					end
					走到(2888.39, -833.456, 160.327)
					走到(2889.64, -829.396, 160.33,1)
					打开身边目标()
					延时(1000)
					朝向坐标(2883.05, -822.697, 160.328)
					按键("w",1)
					if zy=="潜行者" then
						使用技能("潜行")
						延时(2000)
					else
						延时(1700)
					end
					按键("w",2)
					x,y,z = 当前坐标()
					if y>-825 then
						break
					end
				else
					break
				end
			end
		end
		if 在坐标范围(2883.05, -822.697, 160.328,30) then
