function 潜行()
	if zy == "潜行者" and 可循环() then
		while not 存在BUFF("潜行") and 可循环() do 
			使用技能("潜行")
			延时(500)
		end
	elseif zy == "德鲁伊" then
		while not 存在BUFF("潜行") and 可循环() do 
			运行宏("/cast [stance:0/1/2/4]!猎豹形态/n/cast 潜行")
			延时(500)
		end
		
	end
end
