function 转场ZZ()

	while 地图名() == "血色修道院" do
		if HP() <= 1 then
			释放灵魂()
			虚弱复活()
		end
		使用物品("炉石")
		延时(3000)
		while 读条中() do 
			延时(1000)
		end
		延时(5000)
		while 过图中() do 
			延时(1000)
		end
		跳()
		延时(1000)
	end
	if HP()<= 1 then
		ZZ复活()
		if HP() == 1 then
			虚弱复活()
			if HP() == 1 then
				脱离卡死()
				释放灵魂()
				虚弱复活()
			end
		end
	end
	if zhenying == "部落" then
		if 地图名() == "幽暗城" then
			x,y,z = 当前坐标()
			if z < 50 then
				路径走到("幽暗城法师传送到旅店电梯",1595.18, 176.086, -41.4176)
				坐船()
			end
			路径走到("布瑞尔旅店到幽暗电梯上",2024.18, 289.523, 50.534)
		end
		if 小地图名()=="洛丹伦废墟" then
			路径走到("布瑞尔旅店到幽暗电梯上",2024.18, 289.523, 50.534)
		end
		布瑞尔到陶拉祖营地()
		x,y,z = 当前坐标()
		if x > -4400 then
			if 在路径范围("陶阿祖营地到剃刀沼泽") then
				路径走到("陶阿祖营地到剃刀沼泽",-4461.43, -1840.39, 86.7983)
			end
		end
	else
		南海镇到ZZ(1)
	end
