function 剃刀复活()
	if HP() == 0 then
		释放灵魂()
	end
	if HP() == 1 then
		if 在坐标范围(-2516.14, -1961.31, 91.7839,30) then
			走到(-2511.89, -1946.26, 91.7839)
			走到(-2533.44, -1924.41, 92.0282,1)
		end
		if 在坐标范围(-3969.14, -2012.31, 96.7839,30) then
			走到(-3952.89, -2021.26, 96.7839)
			走到(-3972.44, -2038.41, 92.0282,1)
		end
		map = 地图名()
		if map=="贫瘠之地" or map == "剃刀高地" then
			x,y,z = 尸体坐标()
			路径走到("陶阿祖营地到剃刀高地",x,y,z)
			复活()
			while 过图中() do 
				延时(1000)
			end
			if HP() <= 1 then
				路径走到("陶阿祖营地到剃刀高地",-4659.06, -2526.03, 81.4828)
				复活()
				延时(300)
			end
		end
	end
end
function 监狱进本(cz)
	if cz==nil then
		cz=需要重置
	end
	if not 在副本() then
		if 在坐标范围(-8779.98, 836.977, 94.089,40) then
			走到(-8788.51, 827.606, 97.6466,1)
			if cz == 1 and 是否队长() == true then
				队伍拾取()
				重置副本()
				需要重置=0
				if 已重置次数 ~= nil then
					已重置次数=已重置次数+1
					置重置次数(已重置次数)
				end
			end
			while not 在副本() do
				走到(-8772.06, 840.482, 90.9256,1)
				朝向坐标(-8763.13, 847.128, 87.909)
				移动("前",6000)
				for i=1,6 do 
					if 过图中() then
						break
					end
					延时(1000)
				end
				延时(1000)
				while 过图中() do 
					延时(1000)
				end
				if 在副本() then
					return
				end
				走到(-8788.51, 827.606, 97.6466,1)
				while zy=="法师" and 等级() >= 58 and 战斗中() do 
					使用技能("魔爆术")
					延时(1400)
				end
				延时(20000)
				val = 检查挂机方案()
				if val == 11 or val == 22 then
					return
				end
				if 等级() < 30 then
					break
				end
			end
		end
	end
end
function 监狱出本()
	if 在副本() and 地图名()=="监狱" then
		需要重置=1
		路径寻路("监狱出本")
		自动跑()
		延时(3000)
		while 过图中() do 
			延时(1000)
		end
		延时(1000)
		按键("w")
		if not 在副本() then
			走到(-8786.84, 828.974, 97.6513,1)
		end
	end
end
function STSM回血()
	if HP() > 1 and HP()/MaxHP() < 0.6 then
		使用物品("特效治疗药水")
	end
end
function STSM回蓝()
	if HP() > 1 and MP()/MaxMP() < 0.2 then
		使用物品("强效法力药水")
		使用物品("法力黄水晶")
	end
end
function 鹰巢山卖物()
	if 地图名() == "辛特兰" then
		路径走到("鹰巢山西瘟疫",334.069, -2091.51, 131.564)
		打开NPC("哈尔甘")
		for i=1,3 do
			延时(1000)
			出售垃圾()
		end
		走到(340.063, -2099.39, 131.562)
		走到(347.47, -2131.12, 121.839,1)
		路径走到("鹰巢山西瘟疫",293.611, -2116.94, 121.838)
		发送邮件()
		路径走到("鹰巢山到飞机场",282.695, -2001.7, 194.126)
		打开NPC("戈斯鲁姆")
		延时(1000)
		坐飞机到("东瘟疫之地")
		延时(1000)
		while 在飞机上() do 
			延时(1000)
		end
		跳()
		延时(1000)
	end
