function 到STSM()
	if HP() <= 1 or 在副本() then
		return
	end
	沙城回主城()
	到东瘟疫()
	x,y,z = 当前坐标()
	if 地图名() == "东瘟疫之地" and (not 在坐标范围(3227, -4036.57, 108.421,39)) and x < 3187 then
		if 是否队长() then
			队伍拾取()
		end
		延时(300)
		提示("跑本STSM")
		if zy == "法师" then
			使用技能("冰甲术")
		end
		上马()
		if 在坐标范围(2326.44, -5281.33, 81.7971,10) then
			走到(2326.44, -5281.33, 81.7971,1)
		end
		路径走到("东瘟疫到斯坦索姆",3183.01, -4039.87, 107.671)
		下马()
		if 战斗中() then
			清除目标()
			if zy == "法师" then
				使用技能("寒冰护体")
				延时(1400)
			elseif zy  == "圣骑士" then
				使用技能("正义圣印")
				延时(1400)
			end
			while 战斗中() do 
				x,y,z=目标坐标()
				朝向坐标(x,y,z)
				if zy == "法师" then
					使用技能("寒冰箭")
					使用技能("寒冰箭")
					延时(200)
				elseif zy == "圣骑士" then
					技能输出()
				end
				while 读条中() do 
					延时(100)
				end
			end
		end
		路径走到("东瘟疫到斯坦索姆",3183.01, -4039.87, 107.671)
		if HP() <= 1 then
			while HP() <= 1 do
				if HP()==0 then
					x,y,z = 当前坐标()
					if 在坐标范围(3190.28, -4039.69, 107.991,40) then
						释放灵魂()
						路径走到("STSM复活",3190.28, -4039.69, 107.991)
						复活()
						延时(1000)
						if HP() > 1 then
							break
						end
					end
				else
					x,y,z=尸体坐标()
					路径走到("STSM复活",3188.92, -4039.21, 107.991)
					复活()
					延时(1000)
					if HP() == 1 then
						路径走到("东瘟疫到斯坦索姆",x,y,z,25)
						复活()
					end
					使用技能("冰甲术")
					上马()
					路径走到("东瘟疫到斯坦索姆",3183.01, -4039.87, 107.671)
					下马()
				end
				朝向坐标(3227.41, -4036.57, 108.421)
				走到(3192.1, -4039.05, 107.991,1)
				复活()
				延时(1000)
				走到(3183.9, -4038.9, 107.991,1)
			end
		end
		while HP()>1 do
			x,y,z = 当前坐标()
			if x>3187 then
				break
			end
			if 在坐标范围(3183.4, -4039.19, 107.866,5) then
				朝向坐标(3227.41, -4036.57, 108.421)
				打开身边目标()
				延时(300)
				while 读条中() do 
					延时(100)
				end
				移动("前",1500)
				if 在坐标范围(3192.1, -4039.05, 107.991,5) then
					break
				end
			end
			延时(1000)
			走到(3183.9, -4038.9, 107.991,1)
		end	
		x,y,z = 当前坐标()
		if 在坐标范围(3192.1, -4039.05, 107.991,15) and x>3187 then
			if 是否队长() then
				走到(3191.07, -4043.47, 107.992,1)
				num=队伍人数()
				while 坐标范围队员数量(3233.59, -4048.46, 108.444,45)<num-1 do
					打开身边目标()
					延时(7000)
				end
			end
			走到(3227.41, -4036.57, 108.421,1)
			走到(3233.59, -4048.46, 108.444,1)
		end
	end
end
