function 检查回城()
	local 需要回城=0
	if 是否队长() then
		if 背包空格() < 4 or  需要修理()  then
			运行宏("/run SetLootMethod('roundrobin')")
			需要回城=1
		end
	else
		for i=1,10,1 do 
			if 分配方式() == 'roundrobin' then
				需要回城=1
				break
			end
			if 分配方式() == 'group' then
				break
			end
			延时(1000)
		end
	end
	if 需要回城==1 then
		if 阵营() == "联盟" then
			local ls=炉石位置()
			if ls~='蛮锤城堡' then 
				提示('炉石未绑定蛮锤城堡，回铁炉堡')
				使用技能("传送：铁炉堡")
			else
				使用物品("炉石")
			end
			延时(15000)
			while 过图中() do 
				延时(100)
			end
			延时(1000)
		else
			if 背包物品数量("传送符文") > 0 then
				使用技能("传送：幽暗城")
			else
				if 炉石位置() == "幽暗城" then
					使用物品("炉石")
				else
					while 炉石位置() ~= "幽暗城" do
						提示("请把炉石绑定在幽暗城或购买传送符文")
						延时(10000)
						if 背包物品数量("传送符文") > 0 then
							使用技能("传送：幽暗城")
							延时(3000)
							if 读条中() then
								break
							else
								提示("未学习传送幽暗城技能")
							end
						end
					end 
				end
			end
			延时(15000)
			while 过图中() do 
				延时(100)
			end
			延时(1000)
		end
		卖物()
		return true
	end
	return false
end
