function 单点()
	if 战斗中() then
		x,y,z = 当前坐标()
		if 坐标范围怪物数量(x,y,z,60) == 1 then
			选怪("",50,1)
			延时(200)
			x,y,z = 目标坐标()
			if x~=0 then
				走到(x,y,z,1,0,35)
				for fi=1,3 do
					for i=1,10 do 
						x,y,z = 目标坐标()
						朝向坐标(x,y,z)
						延时(100)
						使用技能("寒冰箭")
						延时(100)
						if 读条中() then
							break
						end
						x,y,z = 当前坐标()
						if 坐标范围怪物数量(x,y,z,15)>0 then
							break
						end
					end
					if 读条中() then
						while 读条中() do 
							延时(100)
							x,y,z = 目标坐标()
							朝向坐标(x,y,z)
						end
