function 单点胖子()
	if HP() <= 1 then
		return true
	end
	local ddzz=0
	local x,y,z = 当前坐标()
	if 范围选怪(x,y,z,50,"缝补憎恶")~=0 then
		local x,y,z=当前坐标()
		if 目标的目标是我() == false then
			ddzz=1
			t=0
			if 有目标() then
				while 有目标() do
					for i=1,20 do 
						x,y,z = 目标坐标()
						朝向坐标(x,y,z)
						走到(x,y,z,1,0,35)
						延时(300)
						使用技能("寒冰箭")
						if 读条中() then
							break
						end
						if 目标的目标是我() then
							return false
						end
					end
					while 读条中() do
						延时(100)
						x,y,z = 目标坐标()
						朝向坐标(x,y,z)
					end
					if not 战斗中() then
						break
					end
					t=t+1
					if t>=2 or 坐标范围怪物数量(x,y,z,10) > 0 then
						使用技能("冰霜新星(等级 1)")
						break
					end
				end
				return true
			end
		end
	end
	return false
end
