function 处理眼睛(wait)
	if HP()<=1 then
		return false
	end
	if wait==nil then
		wait=0
	end
	x,y,z = 当前坐标()
	if 范围选怪(x,y,z,23,"纳克萨玛斯之眼")~=0 then
		寻路结束()
		延时(300)
		for fi=1,2 do
			x,y,z=目标坐标()
			if x~=0 then
				for ffi=1,3 do
					x,y,z=目标坐标()
					朝向坐标(x,y,z)
					走到(x,y,z,1,0,19)
					按键("w")
					延时(100)
					if zy == "法师" then
						while 技能可用("火焰冲击") == false do 
							延时(100)
						end
						使用技能("火焰冲击")
						延时(500)
						if not 有目标() or 技能可用("火焰冲击")==false then
							break
						end
					elseif zy == "圣骑士" then
						while 技能可用("驱邪术") == false do 
							延时(100)
						end
						使用技能("驱邪术")
						延时(500)
						if not 有目标() or 技能可用("驱邪术")==false then
							break
						end
					end
				end
				break
			end
		end
		if wait==1 then
			延时(1300)
		end
		return true
	end
	return false
end
