function 等待拉怪(boss,times)
	if HP()<=1 then
		return
	end
	if boss == nil then
		boss=0
	end
	name=""
	使用物品("魔法山泉水")
	使用物品("魔法晶水")
	if boss>0 then
		name = 取单位名称("party1")
	else
		if times==1 or times==3 or times==5 then
			name = 取单位名称("party1")
		else
			if 拉怪队员=="" then
				name = 坐标范围内玩家(3652.68, -3545.39, 137.875,3)
				while name=="" and HP()>1 and 拉怪队员=="" do 
					延时(100)
					name = 坐标范围内玩家(3652.68, -3545.39, 137.875,3)
					if name~="" then
						break
					end
					延时(100)
					name = 坐标范围内玩家(3657.22, -3496.96, 136.573,15)
					if name~="" then
						break
					end
					延时(100)
					name = 坐标范围内玩家(3557.01, -3436.03, 136.242,20)
					if name~="" then
						break
					end
					if 分配方式()=="group" or 分配方式()=="roundrobin" then
						return
					end
				end
				if name~="" then
					拉怪队员=name
				end
			else
				name=拉怪队员
			end
		end
	end
	提示("拉怪的是："..name)
	if name ~= "" then
		while 目标存在BUFF(name,"寒冰屏障") == false and HP()>1 do 
			延时(100)
			if 分配方式()=="group" or 分配方式()=="roundrobin" then
				return
			end
			处理眼睛()
		end
		if HP() == 0 then
			return
		end
		t1=os.clock()
		使用技能("寒冰护体")
		延时(1500)
		使用技能("防护冰霜结界")
		if not 在坐标范围(3638.88, -3588.69, 138.133,2) then
			延时(1400)
		end
		while os.clock()-t1<2.5  and HP()>1 do
			延时(100)
		end
		if times<3 then
			杀怪2()
			杀怪3()
		else
			杀怪4()
		end
	end
end
function 补状态()
	if HP() == 0 then
		return
	end
	清除目标()
	延时(500)
	if 背包物品数量("魔法山泉水") + 背包物品数量("魔法晶水") < 5 then
		使用技能("造水术")
		延时(3500)
	end
	回满()
	if 存在技能("制造魔法玉石") then
		if 背包物品数量("法力刚玉") > 0 then
			销毁物品("法力刚玉",1)
		end
		使用技能("制造魔法玉石")
		延时(3300)
	end
	使用技能("冰甲术")
	延时(1500)
	使用技能("奥术智慧")
