		if HP()==0 then
			if not 在副本() then
				x,y,z  = 当前坐标()
				fb=1
			end
			释放灵魂()
			路径走到("STSM复活",3222.14, -4036.85, 108.384)
			if fb==1 then
				复活()
				走到(3233.59, -4048.46, 108.444,1)
			end
			if 是否队长() then
				队伍拾取()
				if 需要重置 == 1 then
					重置副本()
					需要重置 = 0
				end
			elseif teamNum<1 then
				if 需要重置 == 1 then
					重置副本()
					需要重置 = 0
				end
			end
			走到(3233.59, -4048.46, 108.444,1)
			走到(3234.77, -4051.73, 108.454,1)
			if teamNum<1 or teamNum > 1 and 分配方式()~="group" then
				移动("前",4111)
			end
		end
		if HP() == 1 then
			路径走到("STSM复活",3233.96, -4050.24, 108.449)
			复活()
			走到(3233.59, -4048.46, 108.444,1)
			走到(3234.77, -4051.73, 108.454,1)
			if teamNum<1 or teamNum > 1 and 分配方式()~="group" then
				if 是否队长() then
					队伍拾取()
					if 需要重置 == 1 then
						重置副本()
						需要重置 = 0
					end
				elseif teamNum<1 then
					if 需要重置 == 1 then
						重置副本()
						需要重置 = 0
					end
				end
				走到(3233.59, -4048.46, 108.444,1)
				走到(3234.77, -4051.73, 108.454,1)
				移动("前",4111)
			end
		end
		延时(1000)
		while 过图中() do 
			延时(100)
		end
		延时(1000)
