function STSM进副本(cz)
	if 在副本() then
		return
	end
	if cz==nil then
		cz=0
	end
	if 在坐标范围(3227, -4036, 108.423,40) then
		x,y,z = 当前坐标()
		if x<3222 then
			走到(3227, -4036, 108.423)
		end
		走到(3233.59, -4048.46, 108.444,1)
		延时(1000)
		if 等级()==70 or 是否队长() then
			if 需要重置==1 then
				--[[num=队伍人数()
				if num > 1 then
					while 坐标范围队员数量(3227, -4036, 108.423,40) < num-1 do
						if HP() <= 1 then
							STSM复活()
							复活()
						end
						延时(1000)
					end
				end--]]
				重置副本()
				需要重置=0
				cztime=os.clock()
				if HP() <= 1 then
					STSM复活()
					复活()
				end
				if 是否队长() and HP()>1 then
					运行宏("/p 进本")
					延时(2000)
				end
				需要重置=0
				if 已重置次数 ~= nil then
					已重置次数=已重置次数+1
					置重置次数(已重置次数)
				end
			end
		end
		走到(3234.77, -4051.73, 108.454,1)
		if 等级()==70 or 是否队长() then
			自由拾取()
		else
			延时(1000)
			while 分配方式() ~= "freeforall" and 分配方式()~="master" do 
				if HP() <= 1 then
					STSM复活()
					复活()
				end
				if 是否队长() then
					return
				end
				延时(1000)
			end
		end
		移动("前",2500)
		延时(1000)
		while 过图中() do 
			延时(1000)
		end
		延时(1000)
		if 在副本() then
			return
		else
			while not 在副本() do
				val = 检查挂机方案()
				if val == 11 or val == 22 then
					return
				end
				走到(3233.59, -4048.46, 108.444,1)
				延时(15000)
				走到(3234.77, -4051.73, 108.454)
				移动("前",4000)
				while 过图中() do 
					延时(1000)
				end
				延时(1000)
			end
		end
	end
end
