function 打完修整(波次)
	if 波次 == nil then
		波次=1
	end
	if 存在DEBUFF("死尸虫|食尸鬼瘟疫|鬼魅幻影")  then
		使用技能("寒冰屏障")
		bxtime=os.clock()
		延时(500)
		if 存在DEBUFF("死尸虫|食尸鬼瘟疫|鬼魅幻影") then
			使用技能("急速冷却")
			延时(1000)
			使用技能("寒冰屏障")
			bxtime=os.clock()
			延时(500)
		end
		取消BUFF("寒冰屏障")
	end
	x,y,z = 当前坐标()
	if y<-3580 then
		拾取()
	end
	if 波次>2 then
		拾取2()
		路径走到("STSM2",3602.28, -3489.53, 135.907,1)
	else
		走到(3653.95, -3573.35, 138.086,1)
	end
	if 是否队长() then
		运行宏("/run SetLootMethod('master',UnitName('player'))")
	end
	if HP()>1 then
		while 队伍有死亡() do 
			提示("队伍有死亡，等待其复活")
			延时(5000)
			if HP() == 0 or 分配方式() == "group" then
				break
			end
		end
		if 波次<4 then
			if MP() >1470 then
				使用技能("制造魔法红宝石")
				延时(3500)
			end
			回满()
			if HP() > 1 then
				if 背包物品数量("法力红宝石") < 1 then
					使用技能("制造魔法红宝石")
					延时(3500)
				end
			end
		end
	end
end
