function 前门等待拉怪()
	if HP()<=1 or 分配方式() == "group" or 分配方式() == "roundrobin" then
		return
	end
	name=""
	使用物品("魔法苏打水")
	使用物品("魔法晶水")
	使用物品("魔法山泉水")
	name = 取单位名称("party1")
	提示("拉怪的是："..name)
	if name ~= "" then
		while 目标存在BUFF(name,"寒冰屏障") == false and HP()>1 do 
			延时(100)
			if 分配方式()=="group" or 分配方式()=="roundrobin" then
				return
			end
		end
		if HP() == 0 then
			return
		end
		前门接怪()
		前门杀怪2()
	end
end
