function STSM_3()
	while 队伍人数() < 2 do 
		邀请小号()
		同意进组()
	end
	while 在飞机上() do 
		延时(1000)
	end
	if 等级() == 60 then
		STSM设置勿扰()
	end
	while true do
		邀请小号()
		if 等级() < 54 then
			local ci=0
			while true do 
				STSM复活()
				STSM进副本()
				延时(1000)
				ci=ci+1
				if ci > 60 then
					跳()
					ci=0
