function 暴风城补给()
	local map=地图名()
	if map ~= "暴风城" and map ~= "监狱" then
		使用技能("传送：暴风城")
		延时(15000)
		while 过图中() do 
			延时(1000)
		end
	end
	if 在坐标范围(-8998.29, 861.871, 29.6206,20) then
		走到(-9009.8, 876.095, 29.6206)
		走到(-9018.27, 886.745, 29.6206)
		移动("前",2000)
		走到(-9001.7, 867.996, 142.295)
		走到(-9004.03, 876.908, 137.905)
		走到(-9013.2, 875.381, 132.978)
		走到(-9002.08, 864.915, 129.709,1)
		上马()
		走到(-8995.51, 822.79, 104.75,1)
	end
	local num = 背包物品数量("传送符文")
	if 存在技能("召唤餐桌") then
		num2 = 背包物品数量("魔粉")
	else
		num2 = 100
	end
	if num < 2 then
		走到(-8991.63, 860.146, 126.529)
		走到(-8979.28, 868.747, 122.526)
		移动("前",800)
		闪现走到(-8951.11, 888.383, 108.103)
		走到(-8948.58, 890.881, 108.103)
		走到(-8950.27, 896.944, 109.177,1)
		打开NPC("欧文·沃弗恩")
		延时(1000)
		对话选项(1)
		if num < 2 then
			购买物品(7,20-num)
			延时(100)
		end
		if num2 < 20 then
			购买物品(9,20-num2)
		end
		延时(1000)
		走到(-8948.86, 889.48, 108.104)
		走到(-8956.81, 884.533, 105.703,1)
		上马()
		走到(-8995.51, 822.79, 104.75,1)
	end
	if 在坐标范围(-8995.51, 822.79, 104.75,70) then
		走到(-8995.51, 822.79, 104.75)
		走到(-8989.02, 797.572, 101.623)
		走到(-8967.44, 773.482, 95.1955)
		走到(-8935.31, 773.231, 88.7141)
		走到(-8908.44, 788.225, 87.6685)
		走到(-8880.34, 755.839, 96.2388)
		走到(-8845.68, 781.225, 95.8445)
	end
	if 地图名() == "暴风城" then
		路径走到("监狱修理",-8787.32, 827.403, 97.6469)
	end
end
function 单次监狱(cz)
	监狱进本(cz)
	if 在副本() and 地图名()=="监狱" then
		自由拾取()
		使用技能("奥术智慧")
		延时(1500)
