function 双门收尾(chu)
	while 战斗中() do 
		清除目标()
		使用技能("寒冰护体")
		延时(1500)
		if 坐标范围怪物数量(795.2208862,-522.6564941,-44.78491211,10) >0 then
			使用技能("暴风雪")
			指向坐标(795.2208862,-522.6564941,-44.78491211)
			延时(400)
			if 读条中() then 
				for i=1,8 do 
					延时(1000) 
					if 坐标范围怪物数量(795.2208862,-522.6564941,-44.78491211,10) ==0 then
						break
					end
				end
			end
		end
		if 坐标范围怪物数量(781.2410278,-520.9693604,-51.04761505,10) >0 then
			使用技能("暴风雪")
			指向坐标(781.2410278,-520.9693604,-50.04761505)
			延时(400)
			if 读条中() then 
				for i=1,8 do
					延时(1000) 
					if 坐标范围怪物数量(781.2410278,-520.9693604,-51.04761505,10) ==0 then
						break
					end
				end
			end
		end
		x,y,z = 当前坐标()
		if 坐标范围怪物数量(x,y,z,15) > 0 then
			使用技能("魔爆术")
			延时(1400)
		end
		if 战斗中() then
			if 小鬼剩余数量() >= 1 then
				清除目标()
				延时(3000)
				x,y,z = 目标坐标()
