					使用技能("暴风雪")
					指向坐标(x,y,z)
					延时(400)
					if 读条中() then 
						for i=1,8 do
							延时(1000) 
							if 小鬼剩余数量() ==0 then
								break
							end
						end
					end
				end
			end
		end
	end
	if HP() > 1 then
		if 在坐标范围(781.2410278,-520.9693604,-51.04761505,50) then
			if 队伍人数()>1 then
				运行宏("/p 打怪结束，请老板出副本等待重置")
			end
			if 小鬼剩余数量() == 0 then
				朝向坐标(781.2410278,-520.9693604,-51.04761505)
				移动("前",2700)
			end
		end
		扫地阶段3(chu)
	end
end
function MLD2(shiqu)
	if shiqu == nil then
		shiqu=1
	end
	if HP()==0 then
		释放灵魂()
	end
	邀请小号()
	MLD进本()
	if 地图名() == "玛拉顿" and 在副本() then
		if 需要修理() then
			回城售卖()
			MLD进本()
		end
		MLD跑路()
		邀请小号()
		瀑布拉怪()
		g_shiqu=0
		local fighttimes=0
		while 战斗中() and HP() > 0 do 
			sw=简单杀怪()
			if sw == 2 then
				break
			end
			fighttimes = fighttimes+1
			if fighttimes >10 then
				if MLD_坐标范围精英数量(795.2208862,-522.6564941,-44.78491211,40) == 0 then
					break
				end
			end
			if not 在坐标范围(781.498, -497.127, -42.7763,50) then
				break
			end
		end
		--[[if not 在坐标范围(781.498, -497.127, -42.7763,40) and HP() > 0 then
			传送处理()
		end--]]
		if not 在副本() then
			return
		end
		if shiqu == 1 then
			if HP() > 1 then
				if g_shiqu==1 then
					MLD收尾()
				else
					双门收尾()
				end
			else
				释放灵魂()
			end
		else
			if sw==1 or g_shiqu==1 then
				MLD收尾(1)
			else
				while 战斗中() do 
					上台子()
					清除目标()
					使用技能("寒冰护体")
					延时(1500)
					if 坐标范围怪物数量(795.2208862,-522.6564941,-44.78491211,10) >0 then
						使用技能("暴风雪")
						指向坐标(795.2208862,-522.6564941,-44.78491211)
						延时(400)
						if 读条中() then 
							for i=1,8 do 
								延时(1000) 
								if 坐标范围怪物数量(795.2208862,-522.6564941,-44.78491211,10) ==0 then
									break
								end
							end
						end
					end
					if 坐标范围怪物数量(781.2410278,-520.9693604,-51.04761505,10) >0 then
						使用技能("暴风雪")
						指向坐标(781.2410278,-520.9693604,-50.04761505)
						延时(400)
						if 读条中() then 
							for i=1,8 do
								延时(1000) 
								if 坐标范围怪物数量(781.2410278,-520.9693604,-51.04761505,10) ==0 then
									break
								end
							end
						end
					end
					x,y,z = 当前坐标()
					if 坐标范围怪物数量(x,y,z,8) > 0 then
						使用技能("魔爆术")
					end
					if 战斗中() then
						if 小鬼剩余数量() >= 1 then
							x,y,z = 目标坐标()
							if x~=0 then
								使用技能("暴风雪")
								指向坐标(x,y,z)
								延时(400)
								if 读条中() then 
									for i=1,8 do
										延时(1000) 
										if 小鬼剩余数量() ==0 then
											break
										end
									end
								end
							end
						end
					end
				end
				if HP() > 1 then
					if 队伍人数() > 1 then
						队伍拾取()
					end
					上台子()
					销毁物品("法力蓝宝石",1)
					销毁物品("法力红宝石",1)
					销毁物品("法力黄水晶",1)
					玛拉顿出本()
				end
			end
		end
	end
end
function 血色修理()
	if 需要修理() or 背包空格()<10 then
		local lmap=炉石位置()
		if lmap == "恐惧之末旅店" or lmap=="南海镇" then
			使用物品("炉石")
			延时(15000)
			while 过图中() do 
				延时(1000)
			end
			延时(1000)
		else
			教堂出本()
			走到(2911.85, -824.278, 160.327)
			走到(2909.81, -818.951, 160.327,1)
			if 打开身边目标() then
				延时(500)
				while 读条中() do 
					延时(100)
				end
			end
			走到(2907.68, -816.294, 160.327,1)
			if zhenying == "联盟" then
				while 炉石位置() ~= "南海镇" do
					路径走到("南海镇到血色",-855.53, -569.481, 11.0649)
					if HP() > 1 then
					打开NPC("旅店老板安德森")
					延时(1000)
					对话选项(1)
					延时(1000)
					运行宏("/click StaticPopup1Button1")
					延时(1000)
					else
						if HP() == 0 then
							释放灵魂()
						end
						x,y,z = 尸体坐标()
						自动寻路(x,y,z)
						复活()
					end
				end
			end
			
		end
		if zhenying == "联盟" then
			while not 在坐标范围(2907.68, -816.294, 160.327,30) do
				if 在坐标范围(-851.47, -545.129, 11.0545,120) then
					路径走到("南海镇到血色",-851.47, -545.129, 11.0545)
