					自动寻路(-816.025, -573.763, 15.4053)
					打开NPC("罗伯特·埃比斯彻尔")
					延时(1000)
					出售垃圾()
					延时(1000)
					自动寻路(-796.697, -540.717, 16.4009)
				end
				map=地图名()
				if map=="希尔斯布莱德丘陵" or map=="银松森林" or map == "提瑞斯法林地" then
					if 炉石位置() == "南海镇" then
						路径走到("南海镇到血色",2907.68, -816.294, 160.327)
					end
				else
					路径走到("血色修理路径",949.777, -1434.65, 62.7751)
					打开NPC("莱纳德·波特")
					延时(1000)
					出售垃圾()
					延时(1000)
				end
				if 炉石位置() ~= "南海镇" then
					路径走到("血色修理路径",2907.68, -816.294, 160.327)
				end
				if HP() == 0 then
					释放灵魂()
				end
				if HP()==1 then
					x,y,z = 尸体坐标()
					自动寻路(x,y,z)
					复活()
				end
			end
		else
			路径走到("部落血色修理",2236.97, 254.255, 34.0693)
			发送邮件()
			路径走到("部落血色修理",2248.32, 307.393, 35.1899)
			打开NPC("伊莉莎·考伦")
			延时(500)
			for i=1,2 do 
				延时(1000)
				出售垃圾()
			end
			路径走到("部落血色修理",2907.68, -816.294, 160.327)
			
		end
		if 战斗中() then
			使用技能("寒冰护体")
			延时(1000)
			x,y,z = 目标坐标()
			朝向坐标(x,y,z)
			移动("后",100)
			while 战斗中() do 
				x,y,z = 目标坐标()
				朝向坐标(x,y,z)
				移动("后",200)
				延时(100)
				使用技能("寒冰箭")
				延时(300)
				while 读条中() do 
					延时(100)
				end
				延时(300)
			end
		end
		走到(2910.25, -816.517, 160.329,1,0,0.2)
		打开身边目标()
		延时(1000)
		走到(2908.21, -823.825, 160.329,1)
		if 打开身边目标()  then
			延时(500)
			while 读条中() do 
				延时(100)
			end
		end
		走到(2912.74, -825.01, 160.328,1)
	end
end
