function 血色教堂(shiqu)
	if shiqu==nil then
		shiqu=0
	end
	策略检查()
	邀请小号()
	延时(3000)
	if HP() <= 1 then
		延时(1000)
		释放灵魂()
		路径寻路("血色复活路径")
		复活()
		延时(1000)
		if HP() == 1 then
			教堂进本()
			使用技能("奥术智慧")
			延时(1500)
			使用技能("冰甲术")
			延时(1500)
			回满()
		end
	end
	血色修理()
	if shiqu==0 then
		while 队伍人数()<=1 do 
			提示("等待小号进组")
			延时(1000)
			邀请小号()
			策略检查()
		end
	end
	队伍拾取()
	if not 在副本() then
		if 需要重置 == 1 then
			重置副本()
			需要重置=0
			if 已重置次数 ~= nil then
				已重置次数=已重置次数+1
				置重置次数(已重置次数)
			end
		end
		血色修理()
		教堂进本()
		回满()
	end
	if 在副本() then
		血色进门处理()
		if shiqu ~= 0 then
			摸尸体(40)
		end
		while HP()>1 do
			血色拉怪1()
			if shiqu ~= 0 then
				摸尸体(40)
			end
			if HP() <= 1 then
				延时(1000)
				释放灵魂()
				路径寻路("血色复活路径")
				复活()
				延时(1000)
				if HP() == 1 then
					教堂进本()
					使用技能("奥术智慧")
					延时(1500)
					使用技能("冰甲术")
					延时(1500)
					回满()
				end
			else
				break
			end
		end
		血色拉怪2()
		if shiqu ~= 0 then
			摸尸体(40)
		end
		路径走到("血色出副本",898.391, 1402.14, 18.0232)
		闪现走到(873.871, 1397.59, 18.0062)
		路径寻路("血色出副本")
		--[[mincaiyao,maxcaiyao = 专业信息("草药学")
		if mincaiyao > 120 then
			教堂出本()
			while true do
				走到(2911.85, -824.278, 160.327)
				走到(2909.81, -818.951, 160.327,1,0,0.3)
				if 打开身边目标() then
					延时(500)
					while 读条中() do 
						延时(100)
					end
				end
				走到(2905.48, -808.791, 160.333,1)
				if 在坐标范围(2905.48, -808.791, 160.333,3) then
					break
				end
			end
			XS2进本()
			XS2()
			XS3进本()
			XS3()
			XS1进本()
			XS1()
			教堂进本()
		end--]]
		回复状态()
		血色修理()
		教堂出本()
		if HP() > 1 then
			等待重置时间()
		end
		需要重置=1
	end
end
function 到龙区()
	使用技能("奥术智慧")
	延时(1500)
	使用技能("冰甲术")
	延时(1500)
	x,y,z = 当前坐标()
	if z > -94 and x < -295 then
		return
	end
	路径走到("神庙门口到龙区",-294.944, 52.3876, -91.0234,1)
	回满()
	if 背包物品数量("法力红宝石") < 1 then
		使用技能("制造魔法红宝石")
		延时(3500)
	end
	if 背包物品数量("法力黄水晶") < 1 then
		使用技能("制造魔法黄水晶")
		延时(3500)
	end
	if 背包物品数量("法力翡翠") < 1 then
		使用技能("制造魔法翡翠")
		延时(3500)
	end
	if 队伍人数() > 1 then
		自由拾取()
	end
end
function 台阶1(tt)
	if HP() <= 1 then
		return
	end
	if MP() < 3000 then
		运行宏("/use 强效法力药水/n/use 法力红宝石/n/use 法力黄水晶")
	end
	走到(-297, 97.3042, -91.4669,1)
	for fi=1,30 do 
		if MLD_坐标范围精英数量(-297, 97.3042, -91.4669,30,1)>0 then
			break
		end
		延时(100)
	end
	走到(-296, 101.418, -90.6758)
	延时(100)
	寻路结束()
	x,y,z = 当前坐标()
