	while 坐标范围怪物数量(-287.643, 64.9052, -88.5715,10) == 0 and HP() > 1 do 
		延时(100)
	end
	local nhb=0
	if not 存在BUFF("寒冰护体") then
		nhb=1
	end
	if MP()<300 then
		使用技能("唤醒")
		延时(1000)
