			if tt>=4 and MP()>2000 or 存在BUFF("节能施法") then
				使用技能("暴风雪")
			else
				使用技能("暴风雪(等级 1)")
			end
			指向坐标(-287.775116,70.75535583,-89.159729)
			xx=os.clock()
			延时(1500)
			for i=1,65 do 
				延时(100)
				if os.clock() - xx > 7.9 or not 读条中() then
					break
				end
			end
		end
		if MP() < 2000 then
			运行宏("/use 法力红宝石/n/use 法力黄水晶/n/use 法力翡翠/n/use 强效法力药水")
		end
		使用技能("寒冰护体")
		走到(-308.381, 101.782, -88.5713,1)
		if tt<4 or not 存在BUFF("寒冰护体") then
			while 坐标范围怪物数量(-308.381, 101.782, -88.5713,35) == 0 and HP() > 1 do 
				延时(100)
				if not 战斗中() then
					break
				end
			end
		end
	end
end
