function 最后一个()
	if MLD_坐标范围精英数量(-293.857, 63.7779, -91.467,40,5) == 1 then
		走到(-296.078, 92.2833, -91.467,1)
		while 战斗中() do
			x,y,z = 目标坐标()
			if x~=0 then
				朝向坐标(x,y,z)
				for ii=1,10 do
					使用技能("寒冰箭")
					延时(300)
					if 读条中() then
						break
					end
				end
				while 读条中() do 
					延时(100)
				end
			else
				break
			end
		end
		return true
	end
	return false
end
function 到守望堡()
	if HP() <= 1 then
		return
	end
	local map=地图名()
	if 阵营() == "联盟" then
		if map ~= "悲伤沼泽" and map~="诅咒之地" and map~="阿塔哈卡神庙" then
			if map~="暮色森林" then
				使用物品("炉石")
				延时(15000)
				while 过图中() do 
					延时(1000)
				end
			end
			if 地图名() == "暮色森林" then
				路径走到("夜色镇到飞行点",-10515.5, -1260.05, 41.3642,1)
				打开NPC("菲利希亚·玛林")
				if 坐飞机到("诅咒之地") then
					while 在飞机上() do 
						延时(1000)
					end
					延时(1000)
					跳()
					延时(1000)
				else
					路径走到("夜色镇到守望堡飞行点",-11112.3, -3436.98, 79.0882,1)
					打开NPC("亚莉珊德拉·康斯坦丁")
				end
			end
		end
	end
end
function 暴风到神庙()
	local map = 地图名()
	local feiji=0
	if map=="暴风城" then
		自动寻路(-8837.28, 488.947, 109.612)
		打开NPC("杜加尔·朗德瑞克")
		延时(1500)
		if 坐飞机到("夜色镇") then
			feiji=1
			while 在飞机上() do 
				延时(1000)
			end
		end
	end
	map = 地图名()
	if map == "暴风城" or map == "艾尔文森林" then
		路径走到("暴风城飞行点到夜色镇",-10553.5, -1189.06, 27.9927)
	end
	if 地图名() == "暮色森林" then
		if feiji==0 then
			路径走到("夜色镇到神庙",-10515.5, -1260.05, 41.3642,1)
			打开NPC("菲利希亚·玛林")
			延时(500)
		end
		路径走到("夜色镇到神庙",-10434.8, -2409.93, 67.3647)
	end
	if 地图名() == "逆风小径" then
		路径走到("夜色镇到神庙",-10434.8, -2409.93, 67.3647)
	end
	if 地图名() == "悲伤沼泽" then
		while not 在坐标范围(-10385.4, -3679.25, 18.7704,20) do
			if zy=="潜行者" then
				if not 存在BUFF("潜行") then
					使用技能("潜行")
				end
			end
			路径走到("夜色镇到神庙",-10385.4, -3679.25, 18.7704)
			if HP()==0 then
				释放灵魂()
			end
			if HP()==1 then
				x,y,z = 尸体坐标()
				自动寻路(x,y,z)
				复活()
			end
		end
	end
	map = 地图名()
	if map=="悲伤沼泽" or map=="阿塔哈卡神庙" then
		if zy=="法师" then
			下马()
			使用技能("冰甲术")
		end
		纵向角度(-0.01)
		while not 在坐标范围(-10181.3, -3994.01, -109.368,10) and not 在副本() do
			执行路径文件("守望堡到神庙",-10181.3, -3994.01, -109.368)
			if HP() > 1 then
				if zy=="法师" and 等级() < 60 and 战斗中() then
					使用技能("寒冰屏障")
					延时(10000)
					while 战斗中() do 
						延时(1000)
					end
				end
				if HP() > 1 then
					break
				end
			end
			if HP() <= 1 then
				释放灵魂()
				执行路径文件("神庙复活",-10181.3, -3994.01, -109.368)
				复活()
			end
		end
	end
end
function 到神庙门口()
	if not 在副本() then
		纵向角度(-0.01)
		if 阵营() == "联盟" then
			--到守望堡()
			使用技能("冰甲术")
			延时(1500)
			上马()
