					end
				end
				路径走到("斯通纳德修理",-10364, -3659.9, 23.4906)
			end
		end
		if not 在坐标范围(-10181.3, -3994.01, -109.368,20) then
			上马()
			map=地图名()
			if map == "诅咒之地" then
				执行路径文件("守望堡到神庙",-10181.3, -3994.01, -109.368)
			elseif map == "暮色森林" or map == "悲伤沼泽" or map=="逆风小径" then
				路径走到("夜色镇到神庙",-10385.4, -3679.25, 18.7704)
			end
			执行路径文件("守望堡到神庙",-10181.3, -3994.01, -109.368)
		end
		if 需要重置==1 then
			重置副本()
			需要重置=0
			if 已重置次数 ~= nil then
				已重置次数=已重置次数+1
				置重置次数(已重置次数)
			end
		end
		if HP() > 1 then
			while HP() > 1 and not 在副本() do
				朝向坐标(-10168.72168,-3997.615234,-113.8582458)
				移动("前",5000)
				while 过图中() do 
					延时(1000)
				end
				延时(1000)
				if not 在副本() then
					走到(-10181.3, -3994.01, -109.368,1)
					val = 检查挂机方案()
					if val == 11 or val == 22 then
						return
					end
					延时(30000)
					if 等级() < 60 and 队伍人数() > 1 and not 是否队长() then
						break
					end
				end
			end
		end
	end
end
function 神庙复活()
	local fb=0
	if HP() <= 1 then
		if HP() == 0 then
			if 在副本() then
				fb=1
			end
			释放灵魂()
		end
		if fb==0 then
			x,y,z = 尸体坐标()
			if x~=0 then
				if z < -112 then
					执行路径文件("神庙复活",-10181.3, -3994.01, -109.368)
				else
					执行路径文件("神庙复活",x,y,z)
				end
				复活()
				使用技能("冰甲术")
				延时(1500)
				使用技能("寒冰护体")
				延时(1500)
			end
		end
		执行路径文件("神庙复活",-10181.3, -3994.01, -109.368)
		if 需要重置==1 then
			重置副本()
			需要重置=0
			if 已重置次数 ~= nil then
				已重置次数=已重置次数+1
				置重置次数(已重置次数)
			end
		end
		朝向坐标(-10168.72168,-3997.615234,-113.8582458)
		移动("前",5000)
		while 过图中() do 
			延时(1000)
		end
		延时(1000)
	end
end
function 回城处理()
	if HP() <= 1 then
		return
	end
	if 需要修理() or 背包空格() <= maxfree then
		local lmap=炉石位置()
		if 阵营() == "联盟" or lmap=="夜色镇" then
			if lscheck == 1 then
				while lmap ~= "夜色镇" do 
					提示("炉石需要绑定夜色镇")
					延时(10000)
					lmap=炉石位置()
				end
				if lmap == "夜色镇" then
					local ci=0
					while 小地图名()~="血鸦旅店" and 地图名() ~= "暮色森林" do
						使用物品("炉石")
						延时(15000)
						while 过图中() do 
							延时(1000)
						end
						跳()
					end
				end
			end
			if 在坐标范围(-10547.4, -1157.14, 27.8935,200) then
				路径走到("夜色镇到卡拉赞",-10549.7, -1157.31, 27.7778)
				走到(-10544.7, -1148.9, 26.924)
				走到(-10519.2, -1142.39, 26.9257,1)
				打开NPC("艾瓦特·菲尔伍德")
				for i=1,4 do
					延时(1000)
					出售垃圾()
				end
				走到(-10549.9, -1149.15, 26.8436)
				走到(-10547.4, -1157.14, 27.8935,1)
				发送邮件()
				上马()
			end
		else
			if lscheck == 1 then
				while lmap ~= "斯通纳德" do 
					提示("炉石需要绑定斯通纳德")
					延时(10000)
					lmap=炉石位置()
					val = 检查挂机方案()
					if val == 11 or val == 22 then
						return
					end
				end
				if lmap == "斯通纳德" then
					local ci=0
					while 小地图名()~="斯通纳德" do
						使用物品("炉石")
						延时(15000)
						while 过图中() do 
							延时(1000)
						end
						跳()
					end
				end
			end
			if 地图名() == "悲伤沼泽" then
				路径走到("斯通纳德修理",-10463.3, -3263.75, 20.4762,1)
				发送邮件()
				路径走到("斯通纳德修理",-10409.8, -3266.52, 20.2264,1)
				if 打开NPC("卡尔拉什") then
					延时(1000)
					for i=1,3 do 
						延时(1000)
						出售垃圾()
					end
				end
				路径走到("斯通纳德修理",-10364, -3659.9, 23.4906)
			end
		end
	end
end
function 神庙_绿龙(shiqu)
	minp,maxp=专业信息("剥皮")
	if minp >= 250 and 背包物品数量("剥皮小刀")>0 then
		bopi=1
	else
		bopi=0
	end
	if shiqu==nil then
		shiqu=1
	end
	if HP()==0 then
		释放灵魂()
	end
	策略检查()
	邀请小号()
	神庙复活()
	回城处理()
	到神庙门口()
	if HP()>0 and 在副本() then
		回城处理()
	end
	if 在副本() then
		blvl = 等级()
		if 队伍人数() > 1 then
			自由拾取()
		end
		到龙区()
		if 在坐标范围(-661.951, -47.104, -90.8358,10) or 在坐标范围(-687.727, 41.792, -88.2318,10) then
			if 坐标范围怪物数量(-661.951, -47.104, -90.8358,20) < 2 and not 战斗中() then
				走到(-657.358, -6.12007, -90.8358)
				走到(-638.056, 76.4127, -90.8369)
				走到(-635.887,80.9769,-90.8369)
				走到(-625.264, 85.5704, -90.6354,1)
			end
		end
		if 在坐标范围(-661.951, -47.104, -90.8358,10) or 在坐标范围(-687.727, 41.792, -88.2318,10) or 坐标范围怪物数量(-292.7575989,68.87026215,-91.4670105,25,"",1) > 0 then
			神庙到拉怪点()
			绿龙拉怪()
			local ci=1
			local fh=0
			if fh==0 and not 存在BUFF("防护自然") then
				使用物品("自然防护药水")
				if 存在BUFF("防护自然") then
					fh=1
				end
			end
			while (战斗中() or MLD_坐标范围精英数量(-293.857, 63.7779, -91.467,60,5)>0) and HP() > 1 do 
				if HP() < 1500 then
					运行宏("/use 特效治疗药水/n/use 优质治疗药水")
				end
				台阶1(ci)
				if not 战斗中() and MLD_坐标范围精英数量(-293.857, 63.7779, -91.467,60,5)==0 then
					break
				end
				if 最后一个() then
					break
				end
				台阶下(ci)
				if fh==0 and not 存在BUFF("防护自然") then
					使用物品("自然防护药水")
					if 存在BUFF("防护自然") then
						fh=1
					end
				end
				if 最后一个() then
					break
				end
				if not 战斗中() and MLD_坐标范围精英数量(-293.857, 63.7779, -91.467,60,5)==0 then
					break
				end
				ci=ci+1
				if ci==5 then
					需要重置=1
				end
				台阶2()
				if fh==0 and not 存在BUFF("防护自然") then
					使用物品("自然防护药水")
					if 存在BUFF("防护自然") then
						fh=1
					end
				end
				if 最后一个() then
					break
				end
			end
		end
		if 在坐标范围(-293.857, 63.7779, -91.467,60) then
			神庙收尾(shiqu)
			if 背包物品数量("优质治疗药水") >10 then
				销毁物品("优质治疗药水",1)
			end
			if 背包物品数量("强效法力药水") >10 then
				销毁物品("强效法力药水",1)
			end
		end
		if 队伍人数() > 1 then
			队伍拾取()
			延时(3000)
		end
		if 等级() > blvl then
			法师天赋()
		end
	end
end

function 厄运回城()
	local lmap=炉石位置()
	if lmap ~= "羽月要塞" and lmap ~= "莫沙彻营地" then
		提示("炉石位置不在菲拉斯，请手动去绑定后启动")
		while lmap ~= "羽月要塞" and lmap ~= "莫沙彻营地" do 
			延时(10000)
			lmap=炉石位置()
			按键("space")
		end
		提示("炉石已绑定："..lmap)
	end
	while 小地图名() ~= lmap do
		提示("炉石回城")
		使用物品("炉石")
		延时(12000)
		for i=1,60,1 do 
			if 地图名() == "菲拉斯" then
				break
			end
			延时(1000)
		end
		while 过图中() do 
			延时(1000)
		end
		if 地图名() ~= "菲拉斯" then
			提示("炉石可能未冷却或绑错了地方")
			按键("space")
		end
		延时(1000)
	end
end
