function 小花修理()
	if HP() <= 1 then
		return
	end
	if 需要修理() then
		厄运回城()
	end
end
function 小花复活()
	if HP() <= 1 then
		延时(500)
		释放灵魂()
		x,y,z = 尸体坐标()
		路径走到("厄运东复活",x,y,z)
		复活()
		延时(300)
		if HP()>1 then
		else
			路径寻路("厄运东复活")
		end
		if 需要重置==1 then
			重置副本()
			需要重置=0
			if 已重置次数 ~= nil then
				已重置次数=已重置次数+1
				置重置次数(已重置次数)
			end
		end
		延时(1000)
		x,y,z = 当前坐标()
		if 在坐标范围(-3740.95, 934.519, 161.015,30) then
			while not 在副本() do 
				走到(-3740.95, 934.519, 161.015,1)
				朝向坐标(-3700.95, 934.519, 161.015)
				自动跑()
				延时(5000)
				while 过图中() do 
					延时(1000)
				end
				延时(1000)
				if HP() == 1 then
					x,y,z = 尸体坐标()
					if 阵营()=="联盟" then
						路径走到("羽月要塞到厄运东",x,y,z,25)
						复活()
						使用技能("冰甲术")
						上马()
						路径走到("羽月要塞到厄运东",-3740.95, 934.519, 161.015)
					else
						路径走到("莫沙彻营地到厄运东",x,y,z,25)
						复活()
						使用技能("冰甲术")
						上马()
						路径走到("莫沙彻营地到厄运东",-3740.95, 934.519, 161.015)
					end
				end
			end
			穿装备()
		end
	end
end
function 厄运东小花()
	小花复活()
	小花修理()
	到厄运东()
	策略检查()
	if 在副本() then
		小花1()
		小花2()
		小花3()
		小花4()
		小花5()
		小花6()
		小花7()
		小花8()
		小花出本()
	end
end
