function 闪现到(tarx,tary,tarz,d)
	if zy == "法师" then
		结束寻路()
		x,y,z = 当前坐标()
		朝向坐标(tarx,tary,tarz)
		按键("w",1)
		延时(90)
		按键("w",2)
		使用技能("闪现术")
		local fi=0
		for fi=1,50 do 
			延时(100)
			if not 在坐标范围(x,y,z,5) then
				break
			end
		end
	end
	走到(tarx,tary,tarz,1,0,d)
end
