function 法师传送到(fsmap)
	if 地图名() == fsmap then
		return true
	end
	if zy == "法师" and 背包物品数量("传送符文")>0 then
		if 存在技能("传送："..fsmap) then
			使用技能("传送："..fsmap)
			延时(3000)
			while 读条中() do 
				延时(1000)
			end
			延时(3000)
			while 过图中() do 
				延时(1000)
			end
			if 地图名() == fsmap then
				幽暗城补充材料()
				法师补充()
				return true
			end
		end
	end
	return false
end
