function 奥达曼复活()
	if HP() == 0 then
		释放灵魂()
	end
	if HP() == 1 then
		if 在路径范围("奥达曼后门复活") then
			路径走到("奥达曼后门复活",-6621.73, -3765.47, 266.393)
		elseif 在路径范围("丹莫罗到奥达曼后门") then
			路径走到("丹莫罗到奥达曼后门",-6621.73, -3765.47, 266.393)
		end
		if 在坐标范围(-6621.73, -3765.47, 266.393,10) then
			重置副本()
			fbtime = fbtime + 1
			朝向坐标(-6620.73, -3765.47, 266.393)
			移动("前",5000)
			while 过图中() do 
				延时(1000)
			end
		end
	end
end
