function 法师天赋()
	if zy == "法师" then
		for i=1,7 do
			if 取天赋点数(1,1)<2 then
				加天赋(1,1)
				延时(500)
			else
				break
			end
		end
		for i=1,7 do
			if 取天赋点数(1,2)<3 then
