function 队友掉线()
	if duiyoufs ~= nil then
		if duiyoufs ~= "" and 是否离线(duiyoufs) then
			return true
		end
	end
	return false
end
function 刚进游戏()
	local num=上号时间()
	if num > 0 and num < 3*60*1000 then
		return true
	end
	return false
end
function 上鸟()
	local name = 飞行坐骑名()
	if name ~= "" then
		if not 在马上() then 
			使用物品(name)
			延时(1000)
			while 读条中() do 
				延时(100)
			end
			延时(200)
		end
		按键("space",1)
		延时(200)
		按键("space",2)
	end
end
function 虚空风暴沿路开飞行点()
	while 在飞机上() do 
		延时(1000)
